#!/usr/bin/env python3
"""Real host/net and extracted race-frame logic; fake GK transport and UI."""
from pathlib import Path
import os, subprocess, tempfile
root=Path(__file__).resolve().parents[1]
app=(root/'src/app.c').read_text()
template='#include <assert.h>\n#include <stdio.h>\n#include <string.h>\n#include <sys/socket.h>\n#include <netinet/in.h>\n#include <arpa/inet.h>\nstatic int bind_loopback(int fd,const struct sockaddr *a,socklen_t n){(void)a;assert(n==sizeof(struct sockaddr_in));struct sockaddr_in x={0};x.sin_family=AF_INET;x.sin_addr.s_addr=htonl(INADDR_LOOPBACK);return bind(fd,(const struct sockaddr*)&x,sizeof x);}\n#define bind bind_loopback\n#include "vs_host.c"\n#undef bind\n#include "vs_recovery_wire.h"\ntypedef struct { unsigned char b[1024]; int n,peer; } packet;\nstatic packet q[2400], nq[2400], last_lobby, go; static int qr,qw,nr,nw,phase,go_count;\nint gk_send(int peer,const void *data,int n){const unsigned char *b=data;if(n>=4&&b[3]==GO){go_count++;if(peer==1){memcpy(go.b,b,n);go.n=n;}}if(n>=4&&b[3]==LOBBY&&peer==0){memcpy(last_lobby.b,b,n);last_lobby.n=n;if(phase==0){memcpy(nq[nw].b,b,n);nq[nw].n=n;nq[nw++].peer=-1;}}return n;}\nint gk_recv(void *data,int cap,int *peer){packet *p;if(!phase){if(qr==qw){phase=1;return 0;}p=&q[qr++];}else{if(nr==nw)return 0;p=&nq[nr++];}assert(cap>=p->n);memcpy(data,p->b,p->n);*peer=p->peer;return p->n;}\nvoid car_link_deliver(int pcb,const unsigned char *data,int n){(void)pcb;(void)data;(void)n;}\nstatic void enqueue(int peer,unsigned id,unsigned nonce,unsigned race,unsigned seq,int flag,int ready,int legacy){ packet *p=&q[qw++]; memset(p,0,sizeof *p);p->peer=peer;head(p->b,HELLO);put32(p->b+4,id);p->b[25]=legacy?21:47;p->n=26+p->b[25];unsigned char base[21]={0};if(!legacy){vs_recovery_wire_extension e={(uint8_t)flag,race,nonce,seq};assert(vs_recovery_wire_encode(p->b+26,47,base,21,&e));assert(vs_recovery_wire_put_ready(p->b+26,47,ready));}}\nstatic void resetq(void){qr=qw=nr=nw=phase=0;}\nstatic void setup(int legacy){vs_host_close();resetq();last_lobby.n=go.n=go_count=0;assert(vs_host_open(1,100)==0);assert(vs_host_enable_local());enqueue(0,100,1,0,10,0,0,0);enqueue(1,200,2,0,10,0,0,legacy);vs_host_poll(1,"test");assert(vs_host_control_ready());assert(vs_host_arm_round()&&vs_host_seal_vote()&&vs_host_local_start(1,13,4,10));assert(go_count==6);vs_host_round_accepted();resetq();}\n#include "vs_recovery.h"\n#include <math.h>\n#define VS_GONE 10.0\nstatic double now_ms(void){return 12000;}\nstatic struct {int vs_race,vs_seen_loaded; uint64_t vs_id; net_go vs_go; struct {int finish;} menu;} G;\nstatic struct {vs_recovery recovery; uint32_t race,peer_seq[NET_PLAYERS]; uint64_t peer_nonce[NET_PLAYERS]; unsigned capable,ready_capable,finished;} VR;\nstatic int aborted,menu_frames;\nstatic int vs_abort_to_lobby(void){if(!VR.recovery.initialized || VR.recovery.reason==VS_RECOVERY_NO_ABORT)return 0;aborted++;vs_host_disarm_round();vs_recovery_reset(&VR.recovery);G.vs_race=0;return 1;}\nstatic void menu_frame(int x,double y){(void)x;(void)y;menu_frames++;}\nstatic int vs_recovery_observe_now(void) {\n  const net_lobby *l = net_lobby_valid_now(); uint64_t ids[NET_PLAYERS];\n  if (!VR.recovery.initialized) return 0;\n  double observed_ms = now_ms();\n  if (!isfinite(observed_ms) || observed_ms < 0.0 || observed_ms >= 0x1p63 ||\n      observed_ms < (double)VR.recovery.last_time_ms) {\n    vs_recovery_request_abort(&VR.recovery);\n    return 1;\n  }\n  if (!l->connected || l->n < 1 || l->n > NET_PLAYERS) {\n    /* A GO may arrive without any usable roster. Do not wait indefinitely\n     * when the strict snapshot never becomes available or the socket closes. */\n    if (!net_is_open() || observed_ms - (double)VR.recovery.last_time_ms >= VS_GONE * 1000.0) {\n      vs_recovery_request_abort(&VR.recovery);\n      return 1;\n    }\n    return 0;\n  }\n  /* Race traffic or a delayed GO alone cannot prove the roster is current.\n   * Stop waiting if no strictly valid lobby has arrived for the grace window. */\n  if (net_lobby_valid_silence(observed_ms * 0.001) > VS_GONE) {\n    vs_recovery_request_abort(&VR.recovery);\n    return 1;\n  }\n  uint64_t serial = net_lobby_observations();\n  if (!serial || serial <= VR.recovery.last_serial) return 0;\n  size_t n_ids = 0;\n  for (int i = 0; i < l->n; ++i) {\n    int same_session = 1;\n    if (l->player[i].id != G.vs_id) for (int k = 0; k < G.vs_go.n; ++k) {\n      if (l->player[i].id == G.vs_go.player[k].id && (VR.capable & (1u << k))) {\n        vs_recovery_wire_extension e;\n        same_session = vs_recovery_wire_decode(&e, l->player[i].profile, (size_t)l->player[i].profile_len) && e.nonce == VR.peer_nonce[k];\n        break;\n      }\n    }\n    if (same_session) ids[n_ids++] = l->player[i].id;\n  }\n  for (int k = 0; k < G.vs_go.n; ++k) {\n    if (k == G.vs_go.pcb || !(VR.capable & (1u << k))) continue;\n    for (int i = 0; i < l->n; ++i) if (l->player[i].id == G.vs_go.player[k].id) {\n      vs_recovery_wire_extension e;\n      if (vs_recovery_wire_decode(&e, l->player[i].profile, (size_t)l->player[i].profile_len) &&\n          vs_recovery_wire_accept_peer(&e, VR.peer_nonce[k], VR.race, VR.peer_seq[k])) {\n        VR.peer_seq[k] = e.seq;\n        if (e.flags == VS_RECOVERY_WIRE_ABORT) { vs_recovery_request_abort(&VR.recovery); return 1; }\n        if (VR.ready_capable & (1u << k)) {\n          int loaded;\n          if (vs_recovery_wire_read_ready(l->player[i].profile, (size_t)l->player[i].profile_len, &loaded) && loaded)\n            G.vs_seen_loaded |= 1 << k;\n        }\n        if (e.flags == VS_RECOVERY_WIRE_FINISHED) VR.finished |= 1u << k;\n      }\n      break;\n    }\n  }\n  return vs_recovery_observe(&VR.recovery, VR.race, serial, (int64_t)observed_ms, ids, n_ids) == VS_RECOVERY_EMIT_ABORT;\n}\nstatic void race_frame(void){const char *name="test";unsigned char *profile=NULL;int profile_len=0;double frame_start=0;\n    if (vs_host_is_open()) vs_host_poll(now_ms() * 1e-3, name);\n    net_poll(now_ms() * 1e-3, 1, name, profile, profile_len);\n    if (vs_recovery_observe_now() && vs_abort_to_lobby()) { menu_frame(0, frame_start); return; }\n    /* A local host can observe ABORT followed by NORMAL in one poll, while\n     * the client\'s latest lobby contains only NORMAL. Apply that race-scoped\n     * latch before result processing; it is not evidence of packet delivery. */\n    if (!G.menu.finish && vs_host_is_open() && VR.recovery.initialized &&\n        vs_host_loading_abort(VR.race)) {\n      vs_recovery_request_abort(&VR.recovery);\n      if (vs_abort_to_lobby()) { menu_frame(0, frame_start); return; }\n    }\n}\nstatic void scenario(int finish,int wrongrace){setup(0);assert(net_open_gk(100)==0);G.vs_race=1;G.menu.finish=finish;G.vs_id=100;G.vs_go.n=2;G.vs_go.pcb=0;G.vs_go.player[0].id=100;G.vs_go.player[1].id=200;VR.race=wrongrace?2:1;VR.capable=2;VR.peer_nonce[1]=2;VR.peer_seq[1]=10;VR.ready_capable=0;VR.finished=0;uint64_t ids[]={100,200};assert(vs_recovery_init(&VR.recovery,ids,2,100,VR.race,10000,2000));aborted=menu_frames=0;resetq();enqueue(1,200,2,1,11,1,0,0);enqueue(1,200,2,1,12,0,0,0);race_frame();const net_lobby*l=net_lobby_valid_now();vs_recovery_wire_extension x;assert(l->connected&&vs_recovery_wire_decode(&x,l->player[1].profile,l->player[1].profile_len)&&x.flags==0&&x.seq==12);assert(nw>=2);if(!finish&&!wrongrace){assert(aborted==1&&menu_frames==1&&!vs_host_loading_abort(1));race_frame();assert(aborted==1);}else assert(!aborted);printf("finish=%d wrongrace=%d abort=%d lobby_packets=%d final=NORMAL\\n",finish,wrongrace,aborted,nw);net_close();vs_host_close();}\nint main(void){scenario(0,0);scenario(1,0);scenario(0,1);return 0;}\n'
def block(s, marker):
 p=s.index(marker); i=s.index('{',p)+1; depth=1
 while depth:
  depth+=(s[i]=='{')-(s[i]=='}'); i+=1
 return s[p:i]
template=template.replace('#include "vs_recovery_wire.h"', '#include "vs_recovery_wire.h"\n#include "vs_abort_history.h"\nstatic vs_abort_history VH; static int VH_abort_unknown, VH_has_time; static double VH_last_time;')
old=block(template,'static int vs_recovery_observe_now(void)')
template=template.replace(old,block(app,'static int vs_recovery_observe_now(void)'),1)
a=app.index('    if (vs_host_is_open()) vs_host_poll(now_ms() * 1e-3, name);',app.index('/* a versus: the server hears'))
b=app.index('    /* the host closed its game',a)
start=template.index('    if (vs_host_is_open()) vs_host_poll',template.index('static void race_frame'))
end=template.index('\n}',start)
template=template[:start]+app[a:b].rstrip()+template[end:]
with tempfile.TemporaryDirectory(prefix='race-sticky-',dir=os.environ.get('TMPDIR')) as d:
 p=Path(d)/'test.c';exe=Path(d)/'test';p.write_text(template)
 subprocess.run(['cc','-std=c11','-D__ANDROID__','-Wall','-Wextra','-Werror','-fsanitize=undefined','-fno-sanitize-recover=all','-I'+str(root/'src'),str(p),str(root/'src/net.c'),str(root/'src/vs_recovery_wire.c'),str(root/'src/vs_recovery.c'),str(root/'src/vs_abort_history.c'),'-lm','-o',str(exe)],check=True)
 subprocess.run([str(exe)],check=True)
